-- the kitchen's live orders: a partial index holds only these
CREATE INDEX CONCURRENTLY orders_live ON orders (restaurant_id, placed_at)
  WHERE status IN ('new', 'preparing');

-- take the next delivery job; two workers never get the same one
SELECT id FROM delivery_jobs WHERE state = 'queued'
ORDER BY created_at LIMIT 1
FOR UPDATE SKIP LOCKED;

-- restaurants within 3 km (PostGIS)
SELECT id, name FROM restaurants
WHERE ST_DWithin(location, ST_MakePoint(73.85, 18.52)::geography, 3000);
